; Title tune player
; $8754-$87d5

; Plays the title tune on voices 1 and 2 on odd title ticks. In demo mode, the second pass ends the title.
play_title_tune
        lda title_frame_count           ; MUSPLY in the developer symbol table of the Micro Fun build.
        and #$01
        bne title_tune_note
        rts
title_tune_note
        lda title_note_phase            ; tune_tick $A0 starts a new note.
        cmp #$a0
        bne title_tune_envelope
        lda #$10
        sta VCREG1
        sta VCREG2
        lda #$a8
        sta ATDCY2
        sta SUREL2
        ldx tune_index
        inc tune_index
        inc tune_index
        lda title_tune_voice1,x         ; Voice 1 note.
        asl
        tay
        lda tune_freq_table-$14,y
        sta FRELO1
        lda tune_freq_table-$13,y
        sta FREHI1
        lda title_tune_voice2,x         ; Voice 2 note.
        asl
        tay
        lda tune_freq_table-$14,y
        sta FRELO2
        lda tune_freq_table-$13,y
        sta FREHI2
        lda tune_index
        bne title_tune_envelope         ; One more pass of the whole tune.
        inc tune_loop_count
title_tune_envelope
        lda title_note_phase            ; The sustain of voice 1 falls over the eight ticks of a note.
        eor #$07
        adc #$04
        asl
        asl
        asl
        asl
        sta SUREL1
        lda #$11
        sta VCREG1
        sta VCREG2
        lda title_note_phase
        clc
        adc #$01
        and #$a7
        sta title_note_phase
        lda demo_mode
        beq music_play_exit
        lda tune_loop_count
        cmp #$02
        bne music_play_exit
        lda #$01
        sta title_done
music_play_exit
        rts
